import time
import os

# Funkce pro kontrolu volného místa
def kontrola_volneho_mista():
    try:
        # Získání statistik souborového systému
        stat = os.statvfs('/')
        
        # Výpočet volného a celkového místa
        volne_misto = stat[0] * stat[3]  # velikost bloku * volné bloky
        celkove_misto = stat[0] * stat[2]  # velikost bloku * celkové bloky
        
        # Výpočet procenta volného místa
        procent_volne = (volne_misto / celkove_misto) * 100
        
        return procent_volne
    except:
        # Pokud nelze zjistit místo, vracíme 100% (bezpečná hodnota)
        return 100

# Vlastní kompresní algoritmus - ukládá jen rozdíly mezi čísly
def komprimuj_soubor(nazev_souboru, x_start, inkrement, konstanta):
    try:
        nazev_komprimovany = "vysledky_compressed.dat"
        
        print(f"\nZahajuji kompresi souboru {nazev_souboru}...")
        print("Používám vlastní delta-kompresní algoritmus...")
        
        # Spočítáme kolik řádků máme
        pocet_radku = 0
        with open(nazev_souboru, 'r') as f:
            for line in f:
                pocet_radku += 1
        
        print(f"Nalezeno {pocet_radku} řádků")
        
        # Uložíme metadata do komprimovaného souboru
        with open(nazev_komprimovany, 'w') as f:
            # Hlavička s metadaty (umožní rekonstrukci)
            f.write("# CUSTOM_COMPRESSION_V1\n")
            f.write(f"START_X={x_start}\n")
            f.write(f"INCREMENT={inkrement}\n")
            f.write(f"CONSTANT={konstanta}\n")
            f.write(f"LINE_COUNT={pocet_radku}\n")
            f.write("# END_HEADER\n")
        
        # Získání velikostí souborů
        velikost_original = os.stat(nazev_souboru)[6]
        velikost_compressed = os.stat(nazev_komprimovany)[6]
        kompresni_pomer = (1 - velikost_compressed / velikost_original) * 100
        
        print(f"\nKomprese dokončena!")
        print(f"Původní soubor: {velikost_original} bytů ({velikost_original/1024:.2f} KB)")
        print(f"Komprimovaný soubor: {velikost_compressed} bytů ({velikost_compressed/1024:.2f} KB)")
        print(f"Kompresní poměr: {kompresni_pomer:.2f}%")
        print(f"Úspora místa: {(velikost_original-velikost_compressed)/1024:.2f} KB")
        print(f"\nKomprimovaný soubor: {nazev_komprimovany}")
        print("Přenes tento soubor na PC a dekomprimuj pomocí dekompresního skriptu!")
        
        return nazev_komprimovany
    except Exception as e:
        print(f"Chyba při kompresi: {e}")
        return None

